// THERMOSENSE Emergency PWA Service Worker (sw.js)
// Handles background Push Notifications with requireInteraction=true and emergency deep-linking.

self.addEventListener('install', (event) => {
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(self.clients.claim());
});

self.addEventListener('push', (event) => {
  let data = {
    title: 'THERMOSENSE EMERGENCY SOS',
    body: 'Possible heat-related emergency alert. Tap to view emergency protocol.',
    url: '/?emergency=true'
  };

  if (event.data) {
    try {
      data = event.data.json();
    } catch (e) {
      data.body = event.data.text();
    }
  }

  const options = {
    body: data.body,
    icon: '/favicon.ico',
    badge: '/favicon.ico',
    requireInteraction: true, // Keep notification visible until user interacts
    vibrate: [300, 100, 300, 100, 300],
    data: {
      url: data.url || '/?emergency=true'
    },
    actions: [
      { action: 'open_emergency', title: 'Open Emergency Protocol' },
      { action: 'dismiss', title: 'Dismiss' }
    ]
  };

  event.waitUntil(
    self.registration.showNotification(data.title, options)
  );
});

self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const targetUrl = (event.notification.data && event.notification.data.url) || '/?emergency=true';

  if (event.action === 'dismiss') {
    return;
  }

  event.waitUntil(
    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clientList) => {
      for (let i = 0; i < clientList.length; i++) {
        const client = clientList[i];
        if (client.url && 'focus' in client) {
          client.navigate(targetUrl);
          return client.focus();
        }
      }
      if (self.clients.openWindow) {
        return self.clients.openWindow(targetUrl);
      }
    })
  );
});
